function XMainCameraCM:Start()
    ---@type Engine.Lib.BehaviourAction
    local behaviourAction = self._behaviourAction
    behaviourAction.FixedUpdateAction = function()
        self:OnFixUpdate()
    end
end

function XMainCameraCM:OnFixUpdate()
    if not self.isRunning then
        return
    end
    if self.dt then
        self.animateLen = Mathf.Lerp(self.animateLen, INITIAL_LOCATION, self.dt)
        self.dt = self.dt + Time.deltaTime
        if self.animateLen == INITIAL_LOCATION then
            self.dt = nil
            Events.Broadcast(Constants.EventNames.MainHomeCameraAnimatorResetComplete)
        end
    end

    --if self.isDragging then
    --    if self.angleMove <= (CONSTANTS.ANGLE_MIN - CONSTANTS.ANGLE_SPAN) then
    --        self.angleMove = CONSTANTS.ANGLE_MIN
    --    end
    --    if self.angleMove >= (CONSTANTS.ANGLE_MAX + CONSTANTS.ANGLE_SPAN) then
    --        self.angleMove = CONSTANTS.ANGLE_MAX
    --    end
    --else
    --    if self.angleMove <= CONSTANTS.ANGLE_MIN then
    --        self.angleMove = CONSTANTS.ANGLE_MIN
    --    end
    --    if self.angleMove >= CONSTANTS.ANGLE_MAX then
    --        self.angleMove = CONSTANTS.ANGLE_MAX
    --    end
    --end
    --

    if self.velocity > 0 then
        if self.isRight then
            self.animateLen = self.animateLen + self.velocity / DELTA
        else
            self.animateLen = self.animateLen - self.velocity / DELTA
        end
        self.animateLen = math.min(1, math.max(0, self.animateLen))
        self.velocity = self.velocity - self.snap
        --print('----velocity----', self.velocity, self.animateLen, self.snap)
    end
    ---计算ui类型的显示与旋转
    if self.isDragging then

    else
        ---速度拖动时
        if self.velocity >= 0 and self.isQuickDragging then
            --trailBattleMgr:OnUpdate(self.angleMove)
        else
            if self.isQuickDragging then
                self.isQuickDragging = false
                ---是否计算机器人
            else
                self.isQuickDragging = false
            end
        end
        ---animator的运动
        if (not self.isFinish) and self.velocity <= 0 then
            self.isFinish = true
            Events.Broadcast(Constants.EventNames.ROBOT_HOME_CATE_MOVE, { isFinish = true })
        end
    end
    self._animator:Play(ANIMATION_HASH, -1, Mathf.Clamp01(self.animateLen))
end

---OnSwipeActionEvent
---@param gesture HedgehogTeam.EasyTouch.Gesture
function XMainCameraCM:OnSwipeActionEvent(gesture)
    if not self._isCanSwip then return end
    if gesture then
        if gesture.type == EasyTouch.EvtType.On_SwipeStart then
            self.isFinish = false
            self.startTime = Time.time
            self.velocity = 0
            self.isDragging = false
            self.isQuickDragging = false
        elseif gesture.type == EasyTouch.EvtType.On_Swipe then
        --    ---拖动中
            local direction = (gesture.startPosition.x - gesture.position.x) > 0
            if not self.isDragging then
                self.isDragging = true
                --print('-------xx---->>')
                ---第一次变成拖动状态修改动画状态
                self.preDirection = direction
                Events.Broadcast(Constants.EventNames.ROBOT_HOME_CATE_MOVE, {direction = self.preDirection, isFinish = false})
            end
            if self.preDirection ~= direction then
                self.preDirection = direction
                Events.Broadcast(Constants.EventNames.ROBOT_HOME_CATE_MOVE, {direction = self.preDirection, isFinish = false})
            end
            --self.isDragging = true
            local normalizedPositionX = normalizedPositionX(gesture.deltaPosition.x)
            self.animateLen = self.animateLen - normalizedPositionX
            ---保证结果是 （0，1）
            self.animateLen = math.min(1,math.max(0, self.animateLen))
            --print('--->>', self.animateLen, normalizedPositionX)
            --if gesture.deltaPosition.x < 0 then
            --    ---向右方向
            --    self.angleMove = self.angleMove + newAngle
            --else
            --    ---向左方向
            --    self.angleMove = self.angleMove - newAngle
            --end
            --print('=====',self.angleMove)
            --self._animator:Play(ANIMATION_HASH, -1, Mathf.Clamp01(self.animateLen))
        elseif gesture.type == EasyTouch.EvtType.On_SwipeEnd then
            self.isDragging = false
            ---拖动结束后
            local deltaT = (Time.time - self.startTime)
            if deltaT <= 0.3 then
                self.isQuickDragging = true
                self.velocity = math.abs(normalizedPositionX(gesture.position.x) - normalizedPositionX(gesture.startPosition.x)) / deltaT
                self.snap = self.velocity / 50
                --self.velocity = 0
                --print(self.velocity, self.snap)
                self.isRight = (gesture.startPosition.x - gesture.position.x) > 0
            end
        end
    end
end

